    bild: lookBild("spiegelau-arabesque-bordeauxglas-ambiente-1.webp", 1600, 1296, T("Spiegelau Arabesque: Gläser mit Weiß- und Rotwein auf einer hellen Kücheninsel, dahinter Kochfeld mit Töpfen", "Spiegelau Arabesque: glasses of white and red wine on a light kitchen island, hob with pots behind", "Spiegelau Arabesque : verres de vin blanc et rouge sur un îlot de cuisine clair, plaque de cuisson avec casseroles derrière", "Spiegelau Arabesque: calici di vino bianco e rosso su un'isola chiara, dietro il piano cottura con pentole"), "https://cdn.riedel.com/media/84/67/2b/1791303186/media_4192265_1_lifestyle.aa6f7885.png?width=1920&format=webply&ts=1791303186"),
    produkte: Object.freeze(["spiegelau-arabesque-bordeauxglas"]),
